func TestZigSpecGenerated(t *testing.T) {
	m, err := load(writeRegistry(t, map[string]string{"a.yaml": tsFixture}))
	if err != nil {
		t.Fatal(err)
	}
	src, err := genZigSpec(m)
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{
		"// Code generated by specgen from spec/registry (spec 1.0.0). DO NOT EDIT.\n",
		`pub const schema_url = "https://schemas.o11y.ing/libo11y/1.0.0";`,
		`pub const spec_version = "1.0.0";`,
		`pub const semconv_version = "1.41.0";`,
		`pub const event_name_key = "event.name";`,
		"pub const Outcome = enum {\n    /// The value `success`.\n    success,\n    /// The value `needs-review`.\n    needs_review,\n",
		`    pub const key = "o11y.outcome";`,
		"    pub const all: []const Outcome = &.{ .success, .needs_review };",
		`            .needs_review => "needs-review",`,
		"    pub fn asStr(self: Outcome) []const u8 {",
		"    pub fn parse(s: []const u8) ?Outcome {",
		"pub const attr = struct {",
		`    pub const outcome = "o11y.outcome";`,
		`    pub const tenant_id = "o11y.tenant.id";`,
		"pub const event = struct {",
		`    pub const thing_happened = "o11y.thing.happened";`,
		"pub const metric = struct {",
		`    pub const things = "o11y.things";`,
	} {
		if !strings.Contains(src, want) {
			t.Errorf("genZigSpec missing %s\n%s", want, src)
		}
	}
}

func TestZigTablesGenerated(t *testing.T) {
	m, err := load(writeRegistry(t, map[string]string{"a.yaml": tsFixture}))
	if err != nil {
		t.Fatal(err)
	}
	src, err := genZigTables(m)
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{
		"// Code generated by specgen from spec/registry (spec 1.0.0). DO NOT EDIT.\n",
		`const spec = @import("../../spec.zig");`,
		"pub const sensitivity: []const SensitivityEntry = &.{\n",
		`    .{ .key = "o11y.tenant.id", .class = .internal },`,
		"pub const cardinality: []const CardinalityEntry = &.{\n",
		`    .{ .key = "o11y.outcome", .class = .@"enum" },`,
		`    .{ .key = "o11y.tenant.id", .class = .bounded },`,
		"pub const events: []const EventInfo = &.{\n    .{\n        .name = \"o11y.thing.happened\",\n        .required = &.{\"o11y.outcome\"},\n        .required_templates = &.{},\n    },\n};\n",
		"pub const metrics: []const MetricInfo = &.{\n    .{\n        .name = \"o11y.things\",\n        .instrument = .counter,\n        .unit = \"{thing}\",\n    },\n};\n",
		"pub const rum_span_required: []const SpanShape = &.{\n    .{\n        .name = \"view\",\n        .required = &.{\"o11y.tenant.id\"},\n    },\n};\n",
		"pub const span_required: []const SpanShape = &.{};\n",
		`pub const app_registry_schema = "libo11y.app-registry/v1";`,
		"pub const app_reserved_namespaces: []const []const u8 = &.{\n",
	} {
		if !strings.Contains(src, want) {
			t.Errorf("genZigTables missing %s\n%s", want, src)
		}
	}
}

// TestZigTablesCarryTheRegistry pins the tables the Zig runtime reads
// against the real registry: the resource taxonomy, the requirement levels
// and every classified key.
func TestZigTablesCarryTheRegistry(t *testing.T) {
	m, err := load("../../..")
	if err != nil {
		t.Fatal(err)
	}
	src, err := genZigTables(m)
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{
		"    .{\n        .key = \"service.name\",\n        .tier = \"tier0\",\n        .requirement = .required,\n        .source = \"option-or-env\",\n        .role = \"identifying\",\n    },\n",
		`        .requirement = .conditionally_required,`,
		`        .requirement = .opt_in,`,
		`    .{ .key = "host.ip", .class = .pii },`,
		`    .{ .key = "http.request.header.authorization", .class = .secret },`,
		`    .{ .key = "vcs.revision", .replacement = "vcs.ref.head.revision" },`,
		`        .required_templates = &.{"o11y.config"},`,
		`        .instrument = .histogram,`,
	} {
		if !strings.Contains(src, want) {
			t.Errorf("genZigTables missing %s", want)
		}
	}
	if got, want := strings.Count(src, ", .class = ."), len(m.classByName)+len(m.cardByName); got != want {
		t.Errorf("sensitivity and cardinality tables hold %d entries, want %d", got, want)
	}
}

// TestZigTablesCarryTheAppRegistryRules pins that the Zig validator gets
// every reserved namespace from the Go source of truth, in the sorted
// order the Zig side binary searches.
func TestZigTablesCarryTheAppRegistryRules(t *testing.T) {
	m, err := load(writeRegistry(t, map[string]string{"a.yaml": tsFixture}))
	if err != nil {
		t.Fatal(err)
	}
	src, err := genZigTables(m)
	if err != nil {
		t.Fatal(err)
	}
	const decl = "pub const app_reserved_namespaces: []const []const u8 = &.{\n"
	start := strings.Index(src, decl)
	if start < 0 {
		t.Fatalf("no %q slice in:\n%s", decl, src)
	}
	body, _, _ := strings.Cut(src[start+len(decl):], "};")
	var got []string
	for field := range strings.SplitSeq(body, ",") {
		if field = strings.TrimSpace(field); field != "" {
			got = append(got, strings.Trim(field, `"`))
		}
	}
	if want := appregistry.ReservedNamespaces(); !slices.Equal(got, want) {
		t.Errorf("app_reserved_namespaces = %v, want %v", got, want)
	}
}

func TestZigNames(t *testing.T) {
	for in, want := range map[string]string{
		"o11y.outcome":                  "outcome",
		"o11y.rum.connection.effective": "rum_connection_effective",
		"k8s.pod.uid":                   "k8s_pod_uid",
		"cloud.availability_zone":       "cloud_availability_zone",
		"a-b.c":                         "a_b_c",
		"needs_review":                  "needs_review",
		"slow-2g":                       "slow_2g",
		"iOS":                           "ios",
	} {
		if got := zigSnakeName(in); got != want {
			t.Errorf("zigSnakeName(%q) = %q, want %q", in, got, want)
		}
	}
	for _, tc := range []struct {
		name  string
		field bool
		want  string
	}{
		{"outcome", false, "outcome"},
		{"type", false, `@"type"`},
		{"type", true, "type"},
		{"error", true, `@"error"`},
		{"u8", false, `@"u8"`},
		{"u8", true, "u8"},
		{"i32", false, `@"i32"`},
		{"true", false, `@"true"`},
		{"true", true, "true"},
		{"usize", false, `@"usize"`},
		{"u8x", false, "u8x"},
	} {
		got, ok := zigIdent(tc.name, tc.field)
		if !ok || got != tc.want {
			t.Errorf("zigIdent(%q, %v) = %q, %v, want %q", tc.name, tc.field, got, ok, tc.want)
		}
	}
	for _, bad := range []string{"", "2g", "_", "a b", "a.b"} {
		if got, ok := zigIdent(bad, false); ok {
			t.Errorf("zigIdent(%q) = %q, want a refusal", bad, got)
		}
	}
}

func TestZigQuote(t *testing.T) {
	for in, want := range map[string]string{
		`plain`:      `"plain"`,
		`a "quote"`:  `"a \"quote\""`,
		"line\nfeed": `"line\nfeed"`,
		"tab\there":  `"tab\there"`,
		`back\slash`: `"back\\slash"`,
		"bell\a":     `"bell\x07"`,
		"nul\x00":    `"nul\x00"`,
		"del\x7f":    `"del\x7f"`,
		"nel\u0085":  `"nel\u{85}"`,
		"café":       "\"café\"",
	} {
		if got := zigQuote(in); got != want {
			t.Errorf("zigQuote(%q) = %s, want %s", in, got, want)
		}
	}
}

// TestZigQuotesKeywordNames pins that a registry name that is a Zig keyword
// or primitive still generates, as a quoted identifier, rather than being
// refused or emitted as code that does not compile.
func TestZigQuotesKeywordNames(t *testing.T) {
	m, err := load(writeRegistry(t, map[string]string{"a.yaml": `
groups:
  - id: registry.o11y
    type: attribute_group
    attributes:
      - id: o11y.type
        type:
          members:
            - {id: error, value: "error"}
            - {id: "true", value: "yes"}
        annotations: {o11y.sensitivity: public, o11y.cardinality: enum}
      - id: o11y.u8
        type: string
        annotations: {o11y.sensitivity: internal, o11y.cardinality: bounded}
`}))
	if err != nil {
		t.Fatal(err)
	}
	src, err := genZigSpec(m)
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{
		"pub const Type = enum {",
		"    @\"error\",\n",
		"    true,\n",
		"    pub const all: []const Type = &.{ .@\"error\", .true };",
		`            .@"error" => "error",`,
		`            .true => "yes",`,
		`    pub const @"type" = "o11y.type";`,
		`    pub const @"u8" = "o11y.u8";`,
	} {
		if !strings.Contains(src, want) {
			t.Errorf("genZigSpec missing %s\n%s", want, src)
		}
	}
}

// TestZigRejectsNameCollisions pins that the generator refuses a registry
// whose names would collide in the Zig module, rather than emit code that
// fails to compile or shadows a hand-written type of zig/src/spec.zig.
func TestZigRejectsNameCollisions(t *testing.T) {
	enumAttr := func(id, members string) string {
		return "\ngroups:\n  - id: registry.o11y\n    type: attribute_group\n    attributes:\n      - id: " + id +
			"\n        type:\n          members:\n" + members + "        annotations: {o11y.sensitivity: public, o11y.cardinality: enum}\n"
	}
	cases := []struct {
		name string
		doc  string
		want string
	}{
		{"enum shadows a spec type", enumAttr("o11y.sensitivity", "            - {id: a, value: \"a\"}\n"), "Sensitivity"},
		{"enum shadows the cardinality type", enumAttr("o11y.cardinality", "            - {id: a, value: \"a\"}\n"), "Cardinality"},
		{"minted enum takes the Environment name", enumAttr("o11y.environment", "            - {id: a, value: \"a\"}\n"), "Environment"},
		{"attribute constants collide", `
groups:
  - id: registry.o11y
    type: attribute_group
    attributes:
      - id: o11y.tenant.id
        type: string
        annotations: {o11y.sensitivity: internal, o11y.cardinality: bounded}
      - id: o11y.tenant_id
        type: string
        annotations: {o11y.sensitivity: internal, o11y.cardinality: bounded}
`, "tenant_id"},
		{"variant is not an identifier", enumAttr("o11y.speed", "            - {id: 2g, value: \"2g\"}\n"), "2g"},
		{"two enums become one type", `
groups:
  - id: registry.o11y
    type: attribute_group
    attributes:
      - id: o11y.data.kind
        type:
          members:
            - {id: a, value: "a"}
        annotations: {o11y.sensitivity: public, o11y.cardinality: enum}
      - id: o11y.data_kind
        type:
          members:
            - {id: a, value: "a"}
        annotations: {o11y.sensitivity: public, o11y.cardinality: enum}
`, "DataKind"},
		{"two members become one variant", enumAttr("o11y.speed", "            - {id: slow_2g, value: \"slow-2g\"}\n            - {id: slow.2g, value: \"slow.2g\"}\n"), "slow_2g"},
		{"variant collides with a declaration", enumAttr("o11y.speed", "            - {id: all, value: \"all\"}\n"), "all"},
		{"variant collides with the parse function", enumAttr("o11y.speed", "            - {id: parse, value: \"parse\"}\n"), "parse"},
		{"value holds a backtick", enumAttr("o11y.speed", "            - {id: a, value: \"a`b\"}\n"), "backtick"},
		{"value holds a newline", enumAttr("o11y.speed", "            - {id: a, value: \"a\\nb\"}\n"), "unprintable"},
		{"minted key collides with a copied key", `
groups:
  - id: registry.o11y
    type: attribute_group
    attributes:
      - id: o11y.k8s.pod.uid
        type: string
        annotations: {o11y.sensitivity: internal, o11y.cardinality: bounded}
  - id: libo11y.resource.tier1
    type: attribute_group
    attributes:
      - ref: k8s.pod.uid
        annotations: {o11y.gen: copy}
`, "k8s_pod_uid"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			m, err := load(writeRegistry(t, map[string]string{"a.yaml": tc.doc}))
			if err != nil {
				t.Fatal(err)
			}
			_, err = genZigSpec(m)
			if !errors.Is(err, errZigName) || !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("genZigSpec error = %v, want one naming %q", err, tc.want)
			}
		})
	}
}

// TestZigTablesRejectUnknownClasses pins that an unknown sensitivity or
// cardinality class fails generation instead of being guessed.
func TestZigTablesRejectUnknownClasses(t *testing.T) {
	for _, tc := range []struct{ name, annotations, want string }{
		{"sensitivity", "{o11y.sensitivity: classified, o11y.cardinality: bounded}", `"classified"`},
		{"cardinality", "{o11y.sensitivity: public, o11y.cardinality: huge}", `"huge"`},
	} {
		t.Run(tc.name, func(t *testing.T) {
			m, err := load(writeRegistry(t, map[string]string{"a.yaml": `
groups:
  - id: registry.o11y
    type: attribute_group
    attributes:
      - id: o11y.thing
        type: string
        annotations: ` + tc.annotations + "\n"}))
			if err != nil {
				t.Fatal(err)
			}
			if _, err := genZigTables(m); err == nil || !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("genZigTables error = %v, want one naming %s", err, tc.want)
			}
		})
	}
}

func TestZigGoPrintGenerated(t *testing.T) {
	src := genZigGoPrint()
	header := "// Code generated by specgen from Go's unicode.IsPrint (Unicode " + unicode.Version + "). DO NOT EDIT.\n"
	if !strings.HasPrefix(src, header) {
		t.Fatalf("header: got %q", src[:min(len(src), len(header))])
	}
	const decl = "pub const go_print_ranges: []const [2]u21 = &.{\n"
	start := strings.Index(src, decl)
	if start < 0 {
		t.Fatalf("no go_print_ranges slice in:\n%s", src)
	}
	body, _, _ := strings.Cut(src[start+len(decl):], "};\n")
	pair := regexp.MustCompile(`^    \.\{ ([0-9]+), ([0-9]+) \},$`)
	var got []rune
	for line := range strings.SplitSeq(strings.TrimSuffix(body, "\n"), "\n") {
		match := pair.FindStringSubmatch(line)
		if match == nil {
			t.Fatalf("line %q is not one range", line)
		}
		for _, bound := range match[1:] {
			n, err := strconv.Atoi(bound)
			if err != nil {
				t.Fatal(err)
			}
			got = append(got, rune(n))
		}
	}
	if want := goPrintRanges(); !slices.Equal(got, want) {
		t.Fatalf("go_print_ranges holds %d bounds, want the %d goPrintRanges bounds", len(got), len(want))
	}
}

func TestRenderWritesZig(t *testing.T) {
	m, err := load(writeRegistry(t, map[string]string{"a.yaml": tsFixture}))
	if err != nil {
		t.Fatal(err)
	}
	outputs, err := render(m)
	if err != nil {
		t.Fatal(err)
	}
	for _, rel := range []string{zigSpecPath, zigTablesPath, zigGoPrintPath} {
		if outputs[rel] == "" {
			t.Errorf("render does not write %s", rel)
		}
	}
}

// zigSources renders every generated Zig file for the real registry and the
// layout fixtures, keyed by a name for subtests.
func zigSources(t *testing.T) map[string]string {
	t.Helper()
	sources := map[string]string{"goprint.zig": genZigGoPrint()}
	for name, root := range map[string]string{
		"registry":  "../../..",
		"fixture":   writeRegistry(t, map[string]string{"a.yaml": tsFixture}),
		"longnames": writeRegistry(t, map[string]string{"a.yaml": longNamesFixture}),
		"edges":     writeRegistry(t, map[string]string{"a.yaml": edgesFixture}),
	} {
		m, err := load(root)
		if err != nil {
			t.Fatal(err)
		}
		spec, err := genZigSpec(m)
		if err != nil {
			t.Fatal(err)
		}
		tables, err := genZigTables(m)
		if err != nil {
			t.Fatal(err)
		}
		sources[name+"/spec.zig"] = spec
		sources[name+"/tables.zig"] = tables
	}
	return sources
}

// TestZigOutputIsInZigFmtLayout pins the layout rules that keep the
// generated Zig zig fmt-clean without running zig fmt, which specgen does
// not do so the spec job needs no Zig toolchain: four-space indentation, no
// tabs or trailing space, one blank line at most, multi-line lists with a
// trailing comma and one element per line, and balanced braces. The zig CI
// job's zig fmt --check covers the committed files too.
func TestZigOutputIsInZigFmtLayout(t *testing.T) {
	for name, src := range zigSources(t) {
		t.Run(name, func(t *testing.T) {
			if !strings.HasSuffix(src, "\n") || strings.HasSuffix(src, "\n\n") {
				t.Error("the file must end in exactly one newline")
			}
			depth := 0
			lines := strings.Split(strings.TrimSuffix(src, "\n"), "\n")
			for i, line := range lines {
				where := name + ":" + strconv.Itoa(i+1)
				if strings.ContainsAny(line, "\t\r") {
					t.Errorf("%s: tab or carriage return in %q", where, line)
				}
				if strings.TrimRight(line, " ") != line {
					t.Errorf("%s: trailing space in %q", where, line)
				}
				if line == "" {
					if i > 0 && lines[i-1] == "" {
						t.Errorf("%s: two blank lines in a row", where)
					}
					continue
				}
				code := line
				if strings.HasPrefix(strings.TrimSpace(line), "//") {
					code = ""
				}
				closes := strings.HasPrefix(strings.TrimSpace(code), "}")
				want := depth
				if closes {
					want--
				}
				if indent := len(line) - len(strings.TrimLeft(line, " ")); indent != 4*want {
					t.Errorf("%s: indented %d, want %d: %q", where, indent, 4*want, line)
				}
				depth += zigBraceDelta(code)
				if depth < 0 {
					t.Fatalf("%s: unbalanced braces", where)
				}
				// An opening list or literal that ends its line holds one
				// element per line, each ending in a comma.
				if strings.HasSuffix(code, ".{") && i+1 < len(lines) {
					next := strings.TrimSpace(lines[i+1])
					if !strings.HasPrefix(next, "}") && !strings.HasSuffix(next, ",") && !strings.HasSuffix(next, ".{") {
						t.Errorf("%s: multi-line list element %q lacks a trailing comma", where, next)
					}
				}
			}
			if depth != 0 {
				t.Errorf("unbalanced braces: depth %d at the end", depth)
			}
		})
	}
}

// zigBraceDelta counts the braces a line opens minus those it closes,
// ignoring braces inside string literals.
func zigBraceDelta(line string) int {
	delta, inString := 0, false
	for i := 0; i < len(line); i++ {
		switch c := line[i]; {
		case inString && c == '\\':
			i++
		case c == '"':
			inString = !inString
		case !inString && c == '{':
			delta++
		case !inString && c == '}':
			delta--
		}
	}
	return delta
}

// TestZigOutputIsStable pins that rendering is deterministic, so make
// spec-drift never reports a change the registry did not make.
func TestZigOutputIsStable(t *testing.T) {
	first, second := zigSources(t), zigSources(t)
	for name, src := range first {
		// The fixture roots are temporary directories, which do not appear
		// in the output, so the same name renders the same bytes.
		if second[name] != src {
			t.Errorf("%s renders differently on a second run", name)
		}
	}
}

// TestZigSpecReExportsEveryGeneratedDecl pins that the hand-written
// zig/src/spec.zig, which cannot glob re-export because Zig has no
// usingnamespace, names every public declaration of the generated spec and
// tables files. A registry change that adds an enum or a table fails here
// until spec.zig re-exports it. spec.zig's own comptime test checks the same.
func TestZigSpecReExportsEveryGeneratedDecl(t *testing.T) {
	handWritten, err := os.ReadFile("../../../zig/src/spec.zig")
	if err != nil {
		t.Fatal(err)
	}
	m, err := load("../../..")
	if err != nil {
		t.Fatal(err)
	}
	spec, err := genZigSpec(m)
	if err != nil {
		t.Fatal(err)
	}
	tables, err := genZigTables(m)
	if err != nil {
		t.Fatal(err)
	}
	decl := regexp.MustCompile(`(?m)^pub const ([A-Za-z0-9_]+)[ :]`)
	for file, src := range map[string]string{"spec": spec, "tables": tables, "goprint": genZigGoPrint()} {
		for _, match := range decl.FindAllStringSubmatch(src, -1) {
			want := "pub const " + match[1] + " = generated_" + file + "." + match[1] + ";"
			if !strings.Contains(string(handWritten), want) {
				t.Errorf("zig/src/spec.zig lacks %s", want)
			}
		}
	}
}
